import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/widgets.dart';

class AppBrandAssets {
  AppBrandAssets._();

  static const String alldotdevLogoBase64 = '';
  static Uint8List? _logoBytes;

  static Uint8List get logoBytes {
    _logoBytes ??= base64Decode(alldotdevLogoBase64);
    return _logoBytes!;
  }

  static Widget getLogoWidget({double height = 48, BoxFit fit = BoxFit.contain}) {
    return Image.memory(logoBytes, height: height, fit: fit);
  }
}
